import{_ as t,o,c as n,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Lab 2 · Reading the chain","description":"","frontmatter":{},"headers":[],"relativePath":"labs/lab-2-reading-the-chain.md","filePath":"labs/lab-2-reading-the-chain.md","lastUpdated":null}'),i={name:"labs/lab-2-reading-the-chain.md"};function r(s,e,l,h,c,d){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="lab-2-·-reading-the-chain" tabindex="-1">Lab 2 · Reading the chain <a class="header-anchor" href="#lab-2-·-reading-the-chain" aria-label="Permalink to &quot;Lab 2 · Reading the chain&quot;">​</a></h1><p><strong>Deliverable:</strong> a pull request adding a town activity feed · <strong>Time:</strong> two hours</p><p>Every dApp you will be paid to build shows &quot;what happened recently&quot;. There is no database behind it. The chain stores state — balances, owners, statuses — but <em>what changed and when</em> lives only in event logs, and getting them out is a real engineering problem the moment there is more than a handful.</p><h2 id="the-job" tabindex="-1">The job <a class="header-anchor" href="#the-job" aria-label="Permalink to &quot;The job&quot;">​</a></h2><p>Add a <strong>Town activity</strong> section to Trustville showing the most recent on-chain events across the town, newest first, in language a resident would understand.</p><blockquote><p><code>0x2Ed7…cd94</code> · <code>TicketsBought(1, 0x4F4c…9fA5, 2, 20000000000000000000)</code></p></blockquote><p>is not the deliverable. This is:</p><blockquote><p><strong>Two tickets sold</strong> for the Harvest Festival · 20 TVD · 0x4F4c…9fA5 · 3 minutes ago</p></blockquote><p>Cover at least six event types from at least four contracts — pick ones that tell a story about the town.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>[ ] Shows the most recent 20 events, newest first, merged across contracts.</li><li>[ ] Each row: what happened in plain language, who did it (shortened address), when (relative), and a link to the transaction on the explorer.</li><li>[ ] Amounts formatted as token amounts, not raw wei.</li><li>[ ] New events appear without a manual refresh.</li><li>[ ] An empty chain shows an honest empty state, not a spinner forever.</li><li>[ ] An RPC failure shows an error and recovers when the RPC returns — it does not wedge.</li><li>[ ] Works on a chain with <strong>no explorer configured</strong> (the link is simply absent).</li><li>[ ] Does not slow the first paint of the page. Say in the PR how you ensured that.</li><li>[ ] CI green.</li></ul><h2 id="technical-requirements" tabindex="-1">Technical requirements <a class="header-anchor" href="#technical-requirements" aria-label="Permalink to &quot;Technical requirements&quot;">​</a></h2><p><strong>Bounded queries.</strong> <code>getLogs</code> from block 0 will work on your local chain and fail on DIDLab, which has millions of blocks. Query a bounded window and say in your PR what happens when the town has been quiet for longer than your window. There is no free answer here; there is a decision, and you should be able to defend it.</p><p><strong>Batch, don&#39;t loop.</strong> One <code>getLogs</code> call per contract with multiple event signatures beats one call per event type. Count your RPC calls per refresh and put the number in the PR.</p><p><strong>Decode properly.</strong> Use the generated ABIs and viem&#39;s <code>parseEventLogs</code>. Do not hand-decode topics.</p><p><strong>Updating.</strong> <code>watchContractEvent</code> or polling — your choice, but justify it. Polling every 500ms is a denial-of-service attack on your own RPC node; polling every five minutes is not &quot;live&quot;. Both are defensible; neither is defensible without a reason.</p><p><strong>Clean up.</strong> A component that subscribes must unsubscribe when it unmounts. A leak here shows up as the page getting slower the longer it is open, which is exactly the class of bug nobody notices in a demo and everybody notices in production.</p><h2 id="what-good-looks-like" tabindex="-1">What good looks like <a class="header-anchor" href="#what-good-looks-like" aria-label="Permalink to &quot;What good looks like&quot;">​</a></h2><p>The formatting layer is the interesting design problem. A map from event name to a render function, kept apart from the fetching, is one good answer — a reviewer should be able to add a seventh event type without touching the fetching code. If adding an event means editing three places, the design is wrong.</p><h2 id="common-ways-this-goes-wrong" tabindex="-1">Common ways this goes wrong <a class="header-anchor" href="#common-ways-this-goes-wrong" aria-label="Permalink to &quot;Common ways this goes wrong&quot;">​</a></h2><ul><li><strong>Unbounded <code>fromBlock</code>.</strong> Works locally, times out on DIDLab. Test against both.</li><li><strong>A subscription per event type.</strong> Twelve WebSocket subscriptions is twelve things to leak.</li><li><strong>Assuming logs arrive in order.</strong> They do not, across contracts. Sort by block number and log index.</li><li><strong><code>Date.now()</code> for &quot;3 minutes ago&quot;.</strong> The block has a timestamp; the browser&#39;s clock is not the chain&#39;s clock, and on a local chain where you time-travel they differ by hours.</li><li><strong>Rendering raw BigInt.</strong> <code>20000000000000000000</code> is not a price.</li></ul><h2 id="reality-check" tabindex="-1">Reality check <a class="header-anchor" href="#reality-check" aria-label="Permalink to &quot;Reality check&quot;">​</a></h2><p>Real dApps do not do this. They run an indexer — a service that follows the chain, writes events to a database, and serves them over an API. You are building the thing an indexer replaces, once, so you understand what it is for.</p><p>In your PR description, answer in two or three sentences: <strong>at what point would you stop doing this in the browser and run an indexer, and what would that cost you?</strong></p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>No backend. No indexing service. No new dependencies beyond what is already in <code>app/</code>.</p><h2 id="hand-in" tabindex="-1">Hand in <a class="header-anchor" href="#hand-in" aria-label="Permalink to &quot;Hand in&quot;">​</a></h2><ol><li>The PR, CI green, reviewed and approved.</li><li>Your review of someone else&#39;s PR — check their RPC call count and their cleanup.</li><li>An incident write-up if anything broke.</li></ol>',28)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
